:root {
  --primary: #0A0A23;
  --accent: #FEAC32;
  --link-blue: #002EAD;
  --bg-color: #F5F6F7;
  --card-bg: #FFFFFF;
  --text-main: #1b1b32;
  --text-muted: #858591;
  --border: #d0d0d5;
  --header-bg: #0A0A23;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Inter', system-ui, -apple-system, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.6;
}

a {
  color: var(--link-blue);
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

ul {
  list-style: none;
}

/* Header */
.site-header {
  background-color: var(--header-bg);
  color: #fff;
  padding: 0.5rem 1rem;
  position: sticky;
  top: 0;
  z-index: 100;
}

.header-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.logo {
  font-size: 1.25rem;
  font-weight: 700;
  color: #fff;
  text-decoration: none;
}
.logo a { color: white; text-decoration: none; }

.search-bar {
  flex-grow: 1;
  max-width: 500px;
  display: flex;
}

.search-bar input {
  width: 100%;
  padding: 0.5rem;
  border: none;
  border-radius: 4px;
  font-size: 1rem;
  background: #3b3b4f;
  color: white;
}

.search-bar input::placeholder {
  color: #dfdfe2;
}

.nav-links {
  display: flex;
  gap: 1.5rem;
  align-items: center;
}

.nav-links a {
  color: #fff;
  text-decoration: none;
  font-weight: 500;
}

.nav-links a:hover {
  color: var(--accent);
  text-decoration: none;
}

.menu-toggle {
  display: none;
  background: none;
  border: none;
  color: white;
  font-size: 1.5rem;
  cursor: pointer;
}

/* Banner */
.site-banner {
  background-color: #2a2a40;
  color: #fff;
  text-align: center;
  padding: 0.5rem;
  font-size: 0.9rem;
  font-weight: 500;
}
.site-banner a {
  color: #fff;
  text-decoration: none;
}
.site-banner a:hover { text-decoration: underline; }

/* Main Content */
main {
  max-width: 1200px;
  margin: 2rem auto;
  padding: 0 1rem;
  min-height: 60vh;
}

/* Feature Article */
.featured-article {
  background: var(--card-bg);
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  margin-bottom: 2rem;
  border-radius: 4px;
  overflow: hidden;
  text-decoration: none;
  color: inherit;
}
.featured-article:hover { text-decoration: none; box-shadow: 0 4px 6px rgba(0,0,0,0.1); }

@media(min-width: 768px) {
  .featured-article {
    flex-direction: row;
  }
  .featured-article .img-placeholder {
    width: 60%;
  }
  .featured-article .content {
    width: 40%;
    padding: 2rem;
  }
}

.img-placeholder {
  background: linear-gradient(135deg, #1b1b32, #3b3b4f);
  height: 300px;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 2rem;
  font-weight: bold;
}

.card-tag {
  display: inline-block;
  background: var(--primary);
  color: white;
  padding: 0.25rem 0.5rem;
  font-size: 0.8rem;
  font-weight: bold;
  border-radius: 4px;
  margin-bottom: 1rem;
  text-transform: uppercase;
  z-index: 10;
}

.card-title {
  font-size: 1.5rem;
  margin-bottom: 1rem;
  font-weight: 700;
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: bold;
  font-size: 0.8rem;
}

/* Grid layout */
.section-title {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  border-bottom: 2px solid var(--primary);
  padding-bottom: 0.5rem;
  display: inline-block;
}

.article-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.5rem;
}

@media(min-width: 768px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media(min-width: 1024px) {
  .article-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

.article-card {
  background: var(--card-bg);
  border: 1px solid var(--border);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform 0.2s, box-shadow 0.2s;
}

.article-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

.article-card .img-placeholder {
  height: 180px;
  font-size: 1.2rem;
}

.article-card .content {
  padding: 1.5rem;
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.article-card .card-title {
  font-size: 1.25rem;
  flex-grow: 1;
}

.btn {
  display: inline-block;
  background: var(--primary);
  color: white;
  padding: 0.75rem 1.5rem;
  border: none;
  font-size: 1rem;
  font-weight: bold;
  cursor: pointer;
  text-align: center;
  border-radius: 4px;
}
.btn:hover { background: #1b1b32; color: white; text-decoration: none; }
.btn-accent { background: var(--accent); color: var(--primary); }
.btn-accent:hover { background: #f5a623; color: var(--primary); text-decoration: none; }

.load-more-container {
  text-align: center;
  margin-top: 3rem;
}

/* Footer */
.site-footer {
  background: var(--primary);
  color: #dfdfe2;
  padding: 3rem 1rem;
  margin-top: 4rem;
}

.footer-container {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media(min-width: 768px) {
  .footer-container { grid-template-columns: repeat(3, 1fr); }
}

.footer-col h4 {
  color: white;
  margin-bottom: 1rem;
}

.footer-col p { font-size: 0.9rem; margin-bottom: 1rem; }
.footer-col a { color: #dfdfe2; display: block; margin-bottom: 0.5rem; }
.footer-col a:hover { color: white; }

/* Learn Page styles */
.curriculum-section {
  background: var(--card-bg);
  border: 1px solid var(--border);
  padding: 2rem;
  margin-bottom: 2rem;
}

.curriculum-section h2 { margin-bottom: 1.5rem; }

.curriculum-list li {
  background: var(--bg-color);
  margin-bottom: 0.5rem;
  border: 1px solid var(--border);
  border-radius: 4px;
}
.curriculum-list a {
  display: flex;
  align-items: center;
  padding: 1rem;
  color: var(--text-main);
  font-weight: 500;
  text-decoration: none;
}
.curriculum-list a::before {
  content: '📝';
  margin-right: 1rem;
}
.curriculum-list a:hover { background: #eaeaee; }

.daily-challenge {
  background: #eef2f6;
  border-left: 4px solid var(--link-blue);
  padding: 1.5rem;
  margin-bottom: 2rem;
}

/* Donate Page */
.donate-hero {
  text-align: center;
  max-width: 800px;
  margin: 0 auto 3rem;
}
.donate-hero h1 { font-size: 2.5rem; margin-bottom: 1rem; }

.donate-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
}

@media(min-width: 768px) {
  .donate-container { grid-template-columns: 1fr 1fr; }
}

.donate-card {
  background: var(--card-bg);
  padding: 2rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  text-align: center;
}

.amount-selector {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 1.5rem;
  justify-content: center;
}

.amount-btn {
  background: var(--bg-color);
  border: 2px solid var(--border);
  padding: 0.75rem 1.5rem;
  font-size: 1.2rem;
  font-weight: bold;
  cursor: pointer;
  border-radius: 4px;
  flex: 1;
}

.amount-btn.active {
  background: #fff8e1;
  border-color: var(--accent);
  color: var(--primary);
}

.donate-description {
  font-size: 1.1rem;
  margin-bottom: 1.5rem;
  font-weight: 500;
  min-height: 3rem;
}

.donate-sub {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 1rem;
}

.faq-accordion { margin-top: 3rem; }
.faq-item {
  border-bottom: 1px solid var(--border);
}
.faq-question {
  width: 100%;
  text-align: left;
  background: none;
  border: none;
  padding: 1rem 0;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.faq-question::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--primary);
}
.faq-item.active .faq-question::after { content: '-'; }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  padding: 0;
  color: #4b4b53;
}
.faq-item.active .faq-answer {
  max-height: 500px;
  padding-bottom: 1rem;
}

.impact-list {
  margin-bottom: 2rem;
  padding-left: 1.5rem;
}
.impact-list li { margin-bottom: 0.5rem; }

/* Tag Pages */
.tag-header {
  text-align: center;
  padding: 3rem 1rem;
  background: var(--card-bg);
  border: 1px solid var(--border);
  margin-bottom: 2rem;
}
.tag-header h1 { font-size: 2.5rem; margin-bottom: 0.5rem; text-transform: uppercase; }
.tag-header p { color: var(--text-muted); }

.popular-tags {
  display: flex;
  overflow-x: auto;
  gap: 1rem;
  padding-bottom: 1rem;
  margin-bottom: 2rem;
}
.popular-tags::-webkit-scrollbar { height: 8px; }
.popular-tags::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }

.popular-tag {
  white-space: nowrap;
  background: var(--card-bg);
  border: 1px solid var(--border);
  padding: 0.5rem 1rem;
  border-radius: 20px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-main);
}
.popular-tag span { color: var(--text-muted); margin-left: 0.5rem; font-size: 0.8rem; }
.popular-tag:hover { background: #eef2f6; text-decoration: none; }

/* Mobile adjustments */
@media(max-width: 768px) {
  .nav-links {
    display: none;
    flex-direction: column;
    width: 100%;
    position: absolute;
    top: 100%;
    left: 0;
    background: var(--header-bg);
    padding: 1rem;
    gap: 1rem;
  }
  .nav-links.active {
    display: flex;
  }
  .menu-toggle {
    display: block;
  }
  .search-bar { display: none; }
}

document.addEventListener('DOMContentLoaded', () => {

  // Mobile Menu Toggle
  const menuToggle = document.getElementById('menu-toggle');
  const navLinks = document.getElementById('nav-links');
  if (menuToggle && navLinks) {
    menuToggle.addEventListener('click', () => {
      navLinks.classList.toggle('active');
    });
  }

  // Load More Articles
  const loadMoreBtn = document.getElementById('load-more-articles');
  if (loadMoreBtn) {
    loadMoreBtn.addEventListener('click', () => {
      const grid = document.querySelector('.article-grid');
      if (!grid) return;

      const additionalArticles = [
        { tag: '#Python', title: 'Data Structures in Python - A Beginners Guide', author: 'Eamonn Cottrell', time: '2 days ago' },
        { tag: '#React', title: 'How to Build a Custom Hook in React', author: 'Joel Olawanle', time: '3 days ago' },
        { tag: '#CSS', title: 'Mastering CSS Grid Layouts', author: 'Oluwatobi', time: '5 days ago' }
      ];

      additionalArticles.forEach(article => {
        const card = document.createElement('article');
        card.className = 'article-card';
        card.innerHTML = `
          <div class="img-placeholder">${article.tag}</div>
          <div class="content">
            <a href="#" class="card-tag">${article.tag}</a>
            <h3 class="card-title"><a href="#">${article.title}</a></h3>
            <div class="card-meta">
              <div class="avatar">${article.author.charAt(0)}</div>
              <span>${article.author}</span>
              <span>•</span>
              <span>${article.time}</span>
            </div>
          </div>
        `;
        grid.appendChild(card);
      });

      // Remove button after loading to simulate end of list
      loadMoreBtn.style.display = 'none';
    });
  }

  // Donation Amount Selector
  const amountBtns = document.querySelectorAll('.amount-btn');
  const donateDesc = document.getElementById('donate-description');
  if (amountBtns.length > 0 && donateDesc) {
    amountBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        // Remove active class
        amountBtns.forEach(b => b.classList.remove('active'));
        // Add active to clicked
        btn.classList.add('active');

        const amount = btn.getAttribute('data-amount');
        let hours = 0;
        if (amount === '5') hours = 250;
        if (amount === '10') hours = 500;
        if (amount === '20') hours = 1000;
        if (amount === '40') hours = 2000;

        donateDesc.textContent = \`Your $\${amount} donation will provide \${hours.toLocaleString()} hours of learning to people around the world each month.\`;

        const subLabel = document.querySelector('.donate-sub');
        if (subLabel) {
          subLabel.innerHTML = \`Donating $\${amount} / month: <a href="#">edit amount</a> · Secure donation\`;
        }
      });
    });
  }

  // FAQ Accordion
  const faqItems = document.querySelectorAll('.faq-item');
  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    if (question) {
      question.addEventListener('click', () => {
        const isActive = item.classList.contains('active');

        // Close all other items
        faqItems.forEach(i => i.classList.remove('active'));

        // Toggle current
        if (!isActive) {
          item.classList.add('active');
        }
      });
    }
  });

});

